#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Rebuild the puddle fork's patch stack on a new upstream msb release (fork-only file).

Used by .github/workflows/puddle-autobump.yml. Builds everything locally and pushes nothing:

* msb: every commit on the fork branch since its upstream base, replayed on the new release tag
  per .github/puddle/stack.txt (pick / regenerate / drop), ending in a version commit for
  <release>-puddle.N.
* libkrun leg: when the release pins a newer msb_krun than the fork's libkrun branch is based on,
  the libkrun fork's commits are replayed on that version's commit into branch puddle-<version>.
* russh leg: when the release's Cargo.lock resolves another russh than the fork's russh branch is
  based on, the russh fork's commits are replayed on that tag into branch puddle-<version>.

Legs are built in local clones that cargo reaches through `url.<clone>.insteadOf`, so the new
Cargo.lock pins the exact commits that a later push publishes. Output in --work: report.json,
summary.md, msb.bundle (+ libkrun.bundle, russh.bundle) and candidate.json for the gate jobs.
With --restack the old history is rebuilt as one commit per fix (a manifest names, for every new
commit, the old commits it folds together, and every drop with its reason). Conflict resolutions
are kept by git rerere (--rr-cache), so a conflict solved once stays solved on the next run.

Exit code: 0 replayed, 3 conflict or stack error (summary says what), 1 crash.
"""

import argparse
import datetime
import json
import os
import re
import shutil
import subprocess
import sys
from pathlib import Path

FORK_OWNER = "PuddleHQ"
# Fork owners a Cargo.toml written before the move to PuddleHQ may still name (GitHub redirects them).
OLD_OWNERS = r"(?:PuddleHQ|TijsVK)"
LIBKRUN_URL = f"https://github.com/{FORK_OWNER}/libkrun"
LIBKRUN_UPSTREAM = "https://github.com/superradcompany/libkrun"
LIBKRUN_UPSTREAM_BRANCH = "krun"
RUSSH_URL = f"https://github.com/{FORK_OWNER}/russh"
RUSSH_UPSTREAM = "https://github.com/Eugeny/russh"
IMAGO_URL = f"https://github.com/{FORK_OWNER}/imago"
MARKER = "# puddle fork: patched dependencies (generated by .github/puddle/replay.py)."
BOT = ("puddle auto-bump", "puddle@tijsvankampen.be")


class StackError(Exception):
    """The replay stops here; the message goes into the summary/issue."""


def run(args, cwd=None, check=True, env=None, capture=True):
    p = subprocess.run(args, cwd=cwd, env=env, text=True,
                       stdout=subprocess.PIPE if capture else None,
                       stderr=subprocess.PIPE if capture else None)
    if check and p.returncode != 0:
        raise RuntimeError(f"{' '.join(args)} (in {cwd}) exited {p.returncode}:\n{p.stdout}\n{p.stderr}")
    return p


def git(repo, *args, check=True, env=None):
    return run(["git", *args], cwd=repo, check=check, env=env)


def out(repo, *args):
    return git(repo, *args).stdout.strip()


def semver(v):
    m = re.fullmatch(r"(\d+)\.(\d+)\.(\d+)", v)
    if not m:
        raise StackError(f"not a plain version: {v}")
    return tuple(int(x) for x in m.groups())


def bot_env(extra=None):
    env = dict(os.environ)
    env.update({"GIT_COMMITTER_NAME": BOT[0], "GIT_COMMITTER_EMAIL": BOT[1]})
    if extra:
        env.update(extra)
    return env


def author_env():
    return bot_env({"GIT_AUTHOR_NAME": BOT[0], "GIT_AUTHOR_EMAIL": BOT[1]})


# ------------------------------------------------------------------------------------ manifest
def load_manifest(path):
    rules = []
    for n, line in enumerate(Path(path).read_text().splitlines(), 1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        cols = [c.strip() for c in line.split(" | ")]
        if len(cols) != 4:
            raise StackError(f"{path}:{n}: want 4 columns separated by ' | ', got {len(cols)}")
        action, match, folder, upstream = cols
        if action not in ("pick", "deps", "krun", "russh", "imago", "version") and not action.startswith("rm:"):
            raise StackError(f"{path}:{n}: unknown action {action}")
        rules.append({"line": n, "action": action, "match": match, "folder": folder, "upstream": upstream})
    return rules


def rule_for(rules, subject):
    for r in rules:
        m = r["match"]
        if (m.endswith("*") and subject.startswith(m[:-1])) or subject == m:
            return r
    return None


# --------------------------------------------------------------------------------- cargo helpers
def cargo_toml_pin(text, crate):
    m = re.search(rf'^{re.escape(crate)} = "=([^"]+)"', text, re.M)
    return m.group(1) if m else None


def lock_versions(text, name):
    return re.findall(rf'\[\[package\]\]\nname = "{re.escape(name)}"\nversion = "([^"]+)"', text)


def lock_registry_packages(text, prefix):
    names = set()
    for m in re.finditer(r'\[\[package\]\]\nname = "([^"]+)"\nversion = "[^"]+"\nsource = "([^"]+)"', text):
        if m.group(1).startswith(prefix):
            names.add(m.group(1))
    return sorted(names)


def patch_lines_for(text, url):
    """Crate names that a Cargo.toml patches to `url`."""
    pat = url if OLD_OWNERS in url else re.escape(url)
    return sorted(set(re.findall(rf'^([A-Za-z0-9_-]+) = \{{ git = "{pat}"', text, re.M)))


def cargo_refresh(repo, gitconfig):
    """Let cargo rewrite Cargo.lock for the manifest; fail on an unused [patch]."""
    # Own CARGO_HOME: cargo's GitHub fast path asks api.github.com for a branch head and skips the
    # fetch when its git db already has that commit, which would pin the old fork commit instead of
    # the replayed one when a leg rebuilds a branch name that exists on GitHub.
    env = dict(os.environ, CARGO_NET_GIT_FETCH_WITH_CLI="true", GIT_CONFIG_GLOBAL=str(gitconfig),
               CARGO_HOME=str(Path(gitconfig).parent / "cargo-home"))
    p = run(["cargo", "metadata", "--format-version", "1", "--manifest-path", "Cargo.toml"],
            cwd=repo, env=env, check=False)
    if p.returncode != 0:
        raise StackError(f"cargo metadata failed:\n{p.stderr[-3000:]}")
    unused = [l for l in p.stderr.splitlines() if "was not used in the crate graph" in l]
    if unused:
        raise StackError("a [patch.crates-io] entry is unused (the fix would silently not ship):\n" +
                         "\n".join(unused))


def render_patch_section(krun, russh, imago=None):
    if not krun and not russh and not imago:
        return ""
    lines = ["", MARKER]
    if krun:
        lines.append(f"# libkrun: {FORK_OWNER}/libkrun tag {krun['tag']} = msb_krun {krun['base_version']} "
                     f"plus the puddle libkrun fixes.")
    if russh:
        lines.append(f"# russh: {FORK_OWNER}/russh tag {russh['tag']} = russh {russh['base_version']} "
                     f"plus the puddle russh fix.")
    if imago:
        lines.append(f"# imago: {FORK_OWNER}/imago tag {imago['tag']} = msb-imago {imago['base_version']} "
                     f"plus the puddle fdatasync fix.")
    lines.append("# One tag per base version (a tag names one commit and is never moved), so older fork tags stay buildable.")
    lines.append("[patch.crates-io]")
    for leg, url in ((krun, LIBKRUN_URL), (russh, RUSSH_URL)):
        if leg:
            for crate in leg["crates"]:
                lines.append(f'{crate} = {{ git = "{url}", tag = "{leg["tag"]}" }}')
    if imago:
        lines.append(f'msb-imago = {{ git = "{IMAGO_URL}", tag = "{imago["tag"]}" }}')
    return "\n".join(lines) + "\n"


def write_cargo_toml(repo, krun, russh, pin, imago=None):
    path = Path(repo) / "Cargo.toml"
    text = path.read_text()
    if MARKER in text:
        text = text[: text.index(MARKER)].rstrip("\n") + "\n"
    if "[patch.crates-io]" in text:
        raise StackError("upstream's Cargo.toml has its own [patch.crates-io]; replay.py must learn to merge it")
    if pin:
        for crate in ("msb_krun", "msb_krun_utils"):
            text, n = re.subn(rf'^({crate} = "=)[^"]+(")', rf"\g<1>{pin}\g<2>", text, flags=re.M)
            if n != 1:
                raise StackError(f'Cargo.toml: expected one `{crate} = "=..."` line, found {n}')
    path.write_text(text.rstrip("\n") + "\n" + render_patch_section(krun, russh, imago))


def write_version(repo, old, new):
    path = Path(repo) / "Cargo.toml"
    text = path.read_text()
    text, n1 = re.subn(rf'^version = "{re.escape(old)}"$', f'version = "{new}"', text, count=1, flags=re.M)
    text, n2 = re.subn(rf'"={re.escape(old)}"', f'"={new}"', text)
    if n1 != 1 or n2 == 0:
        raise StackError(f"Cargo.toml: workspace version {old} not found ({n1} version lines, {n2} = pins)")
    path.write_text(text)
    return n2


# ------------------------------------------------------------------------------------ cherry-pick
def unmerged(repo):
    return [l[3:] for l in out(repo, "status", "--porcelain").splitlines()
            if l[:2] in ("UU", "AA", "DU", "UD", "AU", "UA", "DD")]


def pick(repo, sha, lock_ok=False, gitconfig=None):
    """Cherry-pick; returns 'picked', 'empty' or raises StackError on a conflict."""
    p = git(repo, "cherry-pick", "--allow-empty", "--keep-redundant-commits", sha, check=False, env=bot_env())
    if p.returncode == 0:
        if out(repo, "rev-parse", "HEAD^{tree}") == out(repo, "rev-parse", "HEAD~1^{tree}"):
            git(repo, "reset", "-q", "--hard", "HEAD~1")
            return "empty"
        return "picked"
    files = unmerged(repo)
    if not files and git(repo, "diff", "--cached", "--quiet", check=False).returncode != 0:
        # rerere (autoUpdate) replayed a recorded resolution for every conflicted file
        git(repo, "-c", "core.editor=true", "cherry-pick", "--continue", env=bot_env())
        return "picked"
    if files and lock_ok and set(files) <= {"Cargo.lock"}:
        git(repo, "checkout", "--ours", "--", "Cargo.lock")
        cargo_refresh(repo, gitconfig)
        git(repo, "add", "Cargo.lock")
        git(repo, "-c", "core.editor=true", "cherry-pick", "--continue", env=bot_env())
        return "picked"
    if not files and git(repo, "diff", "--cached", "--quiet", check=False).returncode == 0:
        git(repo, "cherry-pick", "--skip", check=False)
        return "empty"
    detail = git(repo, "diff", check=False).stdout[:6000]
    git(repo, "cherry-pick", "--abort", check=False)
    raise StackError(f"conflict replaying {sha[:12]} `{out(repo, 'log', '-1', '--format=%s', sha)}` "
                     f"in: {', '.join(files) or '(none listed)'}\n\n```diff\n{detail}\n```")


# ---------------------------------------------------------------------------------------- legs
def ensure_clone(path, url, upstream_url):
    if not (path / ".git").exists():
        run(["git", "clone", "-q", "--no-checkout", url, str(path)])
        git(path, "remote", "add", "upstream", upstream_url)
        git(path, "remote", "set-url", "--push", "upstream", "DISABLED")
    git(path, "fetch", "-q", "--tags", "origin")
    git(path, "config", "user.name", BOT[0])
    git(path, "config", "user.email", BOT[1])


def published_leg(path, tag, sha):
    """Tags never move: when origin already has `tag`, its tree must equal the rebuilt one, and the
    published commit is used instead (no bundle, nothing pushed). Returns that commit, or None."""
    have = out(path, "ls-remote", "origin", f"refs/tags/{tag}")
    if not have:
        return None
    git(path, "fetch", "-q", "origin", f"refs/tags/{tag}:refs/tags/{tag}", "--force")
    pub = out(path, "rev-parse", f"refs/tags/{tag}^{{commit}}")
    if out(path, "rev-parse", f"{pub}^{{tree}}") != out(path, "rev-parse", f"{sha}^{{tree}}"):
        raise StackError(f"{path.name}: tag {tag} is published at {pub[:12]} with another tree than the rebuilt "
                         f"{sha[:12]}; tags never move, so the leg needs the next puddle.N")
    return pub


def replay_leg(path, base, commits, branch, tag):
    git(path, "checkout", "-q", "-f", "-B", branch, base)
    kept, dropped = [], []
    for c in commits:
        subj = out(path, "log", "-1", "--format=%s", c)
        r = pick(path, c)
        (kept if r == "picked" else dropped).append(subj)
    # The tag is what the manifest pins; land.sh pushes it (annotated) with the branch.
    git(path, "tag", "-f", tag, "HEAD")
    return out(path, "rev-parse", "HEAD"), kept, dropped


def krun_base_for(path, version):
    """Commit of superradcompany/libkrun that msb_krun <version> was published from."""
    try:
        import io, tarfile, urllib.request
        req = urllib.request.Request(f"https://static.crates.io/crates/msb_krun/msb_krun-{version}.crate",
                                     headers={"User-Agent": "puddle-autobump (puddle@tijsvankampen.be)"})
        data = urllib.request.urlopen(req, timeout=60).read()
        with tarfile.open(fileobj=io.BytesIO(data), mode="r:gz") as t:
            info = json.load(t.extractfile(f"msb_krun-{version}/.cargo_vcs_info.json"))
        sha = info["git"]["sha1"]
        git(path, "fetch", "-q", "upstream", sha)
        return sha, "crates.io .cargo_vcs_info.json"
    except Exception as e:  # unpublished (as 0.1.41 was) or no vcs info: find the bump commit
        git(path, "fetch", "-q", "upstream", LIBKRUN_UPSTREAM_BRANCH)
        for c in out(path, "rev-list", "--reverse", f"upstream/{LIBKRUN_UPSTREAM_BRANCH}", "--",
                     "src/krun/Cargo.toml").splitlines():
            if re.search(rf'^version = "{re.escape(version)}"$',
                         out(path, "show", f"{c}:src/krun/Cargo.toml"), re.M):
                return c, f"first krun commit with src/krun/Cargo.toml version {version} ({e.__class__.__name__} on crates.io)"
        raise StackError(f"no superradcompany/libkrun commit found for msb_krun {version}")


def krun_version_at(path, rev):
    m = re.search(r'^version = "([^"]+)"$', out(path, "show", f"{rev}:src/krun/Cargo.toml"), re.M)
    return m.group(1)


def libkrun_leg(args, cur_toml, new_lock, up_pin):
    cur_pin = re.search(rf'git = "https://github.com/{OLD_OWNERS}/libkrun", (branch|tag) = "([^"]+)"', cur_toml)
    if not cur_pin:
        return None, {"leg": "libkrun", "state": "not wired"}
    cur_kind, cur_branch = cur_pin.groups()
    path = Path(args.work) / "libkrun"
    ensure_clone(path, LIBKRUN_URL, LIBKRUN_UPSTREAM)
    git(path, "fetch", "-q", "upstream", LIBKRUN_UPSTREAM_BRANCH)
    cur_tip = out(path, "rev-parse", f"refs/tags/{cur_branch}^{{commit}}" if cur_kind == "tag" else f"origin/{cur_branch}")
    cur_base = out(path, "merge-base", cur_tip, f"upstream/{LIBKRUN_UPSTREAM_BRANCH}")
    cur_ver = krun_version_at(path, cur_base)
    commits = out(path, "rev-list", "--reverse", "--no-merges", f"{cur_base}..{cur_tip}").splitlines()
    crates = lock_registry_packages(new_lock, "msb_krun")
    info = {"leg": "libkrun", "current_branch": cur_branch, "current_base": cur_base,
            "current_version": cur_ver, "release_pin": up_pin}
    moved = semver(up_pin) > semver(cur_ver)
    if not moved and not args.force_legs:
        info["state"] = "unchanged"
        return {"tag": cur_branch, "sha": cur_tip, "base_version": cur_ver, "pin": cur_ver,
                "crates": crates, "local": False}, info
    target = up_pin if moved else cur_ver
    base, how = (krun_base_for(path, target) if moved else (cur_base, "current base (forced)"))
    branch = f"puddle-{target}"
    tag = f"msb_krun-v{target}-puddle.1"
    tip, kept, dropped = replay_leg(path, base, commits, branch, tag)
    info.update({"state": "replayed", "branch": branch, "tag": tag, "base": base, "base_found_by": how,
                 "kept": kept, "dropped": dropped, "sha": tip,
                 "tree_equal_to_current": out(path, "rev-parse", f"{tip}^{{tree}}") ==
                 out(path, "rev-parse", f"{cur_tip}^{{tree}}")})
    if not kept:
        info["state"] = "all fixes upstream: patch dropped"
        return None, info
    return {"branch": branch, "tag": tag, "sha": tip, "base": base, "base_version": target, "pin": target,
            "crates": crates, "local": True, "path": str(path)}, info


def russh_leg(args, cur_toml, new_lock):
    m = re.search(rf'git = "https://github.com/{OLD_OWNERS}/russh", (?:branch = "puddle-([^"]+)"|tag = "v([0-9][^"]*)-puddle\.\d+")',
                  cur_toml)
    if not m:
        return None, {"leg": "russh", "state": "not wired"}
    cur_ver = m.group(1) or m.group(2)
    cur_branch = f"puddle-{cur_ver}"
    cur_tag = re.search(rf'git = "https://github.com/{OLD_OWNERS}/russh", tag = "([^"]+)"', cur_toml)
    crates = patch_lines_for(cur_toml, f"https://github.com/{OLD_OWNERS}/russh")
    vers = lock_versions(new_lock, "russh")
    if len(vers) != 1:
        raise StackError(f"release Cargo.lock has {len(vers)} russh versions ({vers}); expected one")
    rel = vers[0]
    path = Path(args.work) / "russh"
    ensure_clone(path, RUSSH_URL, RUSSH_UPSTREAM)
    git(path, "fetch", "-q", "upstream", "tag", f"v{cur_ver}", "--no-tags")
    cur_tip = out(path, "rev-parse", f"refs/tags/{cur_tag.group(1)}^{{commit}}" if cur_tag else f"origin/{cur_branch}")
    info = {"leg": "russh", "current_branch": cur_branch, "current_version": cur_ver, "release_lock": rel}
    if rel == cur_ver and not args.force_legs:
        info["state"] = "unchanged"
        return {"tag": cur_tag.group(1), "sha": cur_tip, "base_version": cur_ver, "crates": crates,
                "local": False}, info
    commits = out(path, "rev-list", "--reverse", "--no-merges", f"v{cur_ver}..{cur_tip}").splitlines()
    git(path, "fetch", "-q", "upstream", "tag", f"v{rel}", "--no-tags")
    base = out(path, "rev-parse", f"v{rel}^{{commit}}")
    branch = f"puddle-{rel}"
    tag = f"v{rel}-puddle.1"
    tip, kept, dropped = replay_leg(path, base, commits, branch, tag)
    info.update({"state": "replayed", "branch": branch, "tag": tag, "base": base, "kept": kept, "dropped": dropped,
                 "sha": tip, "tree_equal_to_current": out(path, "rev-parse", f"{tip}^{{tree}}") ==
                 out(path, "rev-parse", f"{cur_tip}^{{tree}}")})
    if not kept:
        info["state"] = "fix upstream: patch dropped"
        return None, info
    pub = published_leg(path, tag, tip)
    if pub:
        info.update({"state": "published", "sha": pub})
    return {"branch": branch, "tag": tag, "sha": pub or tip, "base": base, "base_version": rel, "crates": crates,
            "local": pub is None, "path": str(path)}, info


def imago_leg(cur_toml, new_lock):
    """The imago fork is one tag on msb-imago's published base; it cannot be replayed here.

    Kept while the release still resolves the msb-imago version the tag is based on; otherwise the
    replay stops, because a tag on the wrong base would silently ship the old crate's code."""
    m = re.search(rf'msb-imago = \{{ git = "https://github.com/{OLD_OWNERS}/imago", tag = "v([0-9.]+)-puddle\.(\d+)" \}}', cur_toml)
    if not m:
        return None, {"leg": "imago", "state": "not wired"}
    base, n = m.group(1), m.group(2)
    tag = f"v{base}-puddle.{n}"
    vers = lock_versions(new_lock, "msb-imago")
    if len(vers) != 1:
        raise StackError(f"release Cargo.lock has {len(vers)} msb-imago versions ({vers}); expected one")
    info = {"leg": "imago", "current_branch": tag, "current_version": base, "release_lock": vers[0]}
    if vers[0] != base:
        raise StackError(
            f"the release resolves msb-imago {vers[0]}, the puddle fork's {FORK_OWNER}/imago tag {tag} is "
            f"msb-imago {base}. Rebase the fdatasync fix (upstream-issues/msb-guest-fsync-latency/fix.patch) "
            f"onto msb-imago {vers[0]} (or drop the stack line if upstream has it), tag it "
            f"v{vers[0]}-puddle.1, and change the tag in this repository's Cargo.toml [patch.crates-io].")
    info["state"] = "unchanged"
    return {"tag": tag, "base_version": base, "crates": ["msb-imago"], "local": False}, info


# --------------------------------------------------------------------------------------- rerere
def enable_rerere(repo, rr_cache=None):
    """Record conflict resolutions so a conflict solved once stays solved on every later run.

    With --rr-cache the resolutions live outside the clone (e.g. checked in next to stack.txt) and
    are copied in before the run and back after it (sync_rerere)."""
    git(repo, "config", "rerere.enabled", "true")
    git(repo, "config", "rerere.autoUpdate", "true")
    if rr_cache:
        src, dst = Path(rr_cache), Path(repo) / out(repo, "rev-parse", "--git-path", "rr-cache")
        if src.is_dir():
            shutil.copytree(src, dst, dirs_exist_ok=True)


def sync_rerere(repo, rr_cache):
    if rr_cache:
        src = Path(repo) / out(repo, "rev-parse", "--git-path", "rr-cache")
        if src.is_dir():
            shutil.copytree(src, Path(rr_cache), dirs_exist_ok=True)


# -------------------------------------------------------------------------------------- restack
# The restack manifest turns the fork's history (one commit per change, fix follow-ups and stack
# lines included) into one commit per fix on a new base. One line per new commit or drop:
#
#   kind | subject | folder | upstream | sources
#
#   fix      one commit per fix; its sources (old commits, in order) are squashed into it. A subject
#            of "=" takes the first source's subject.
#   drop     the sources are not replayed; subject says why (e.g. "upstream #1822 in v0.7.10")
#   deps     the fork-dependency commit ([patch.crates-io] for every leg), regenerated
#   ci       the fork's CI commit; .github/puddle/stack.txt is regenerated from this manifest and
#            .github/puddle/replay.py is this script. A source "rm:PATH=SHA" deletes PATH.
#   version  the version commit, regenerated last
#   krun-fix / krun-drop   the same for the libkrun leg (sources are libkrun fork commits)
#   source REF / krun-source REF   (no columns) a branch whose commits must all be listed
#
# Every commit of the old stack (first parent since its upstream base) and of every `source` branch
# must be listed exactly once, so nothing is lost silently.
RESTACK_KINDS = ("fix", "drop", "deps", "ci", "version", "krun-fix", "krun-drop")
OWN_PATHS = (".github/puddle/stack.txt", ".github/puddle/replay.py")


def load_restack(path):
    steps, sources, krun_sources = [], [], []
    for n, line in enumerate(Path(path).read_text().splitlines(), 1):
        if not line.strip() or line.lstrip().startswith("#"):
            continue
        word = line.split()[0]
        if word in ("source", "krun-source"):
            (sources if word == "source" else krun_sources).append(line.split()[1])
            continue
        cols = [c.strip() for c in line.split(" | ")]
        if len(cols) != 5:
            raise StackError(f"{path}:{n}: want 5 columns separated by ' | ', got {len(cols)}")
        kind, subject, folder, upstream, srcs = cols
        if kind not in RESTACK_KINDS:
            raise StackError(f"{path}:{n}: unknown kind {kind}")
        steps.append({"line": n, "kind": kind, "subject": subject, "folder": folder, "upstream": upstream,
                      "sources": srcs.split() if srcs != "-" else []})
    return steps, sources, krun_sources


def covered(src):
    """The old commit a manifest source stands for: rm:PATH=OLD and OLD>NEW (OLD rebased by hand
    as NEW, which is what gets applied) both cover OLD. OLD>- covers OLD and applies nothing: it
    is folded into a NEW listed earlier in the same step (several old commits, one redo)."""
    if src.startswith("rm:"):
        return src.split("=", 1)[1]
    return src.split(">", 1)[0]


def applied(src):
    return src.split(">", 1)[1] if ">" in src and not src.startswith("rm:") else src


def full_sha(repo, ref):
    p = git(repo, "rev-parse", "--verify", "-q", f"{ref}^{{commit}}", check=False)
    if p.returncode != 0:
        raise StackError(f"{repo}: unknown commit {ref} (fetch the branch that has it)")
    return p.stdout.strip()


def check_coverage(repo, steps, expected, what):
    """Every expected commit is listed once; nothing is listed twice."""
    seen = {}
    for st in steps:
        for s in st["sources"]:
            sha = full_sha(repo, covered(s))
            if sha in seen:
                raise StackError(f"{what}: {sha[:12]} listed on lines {seen[sha]} and {st['line']}")
            seen[sha] = st["line"]
    missing = [c for c in expected if c not in seen]
    if missing:
        raise StackError(f"{what}: commits not in the restack manifest (add a fix or drop line):\n" +
                         "\n".join(f"- {c[:12]} {out(repo, 'log', '-1', '--format=%s', c)}" for c in missing))
    return seen


def apply_source(repo, src, gitconfig, skip_paths=OWN_PATHS):
    """Apply one source commit to the index without committing. Returns the conflicted paths
    left after rerere (empty on success)."""
    if src.startswith("rm:"):
        path = src[3:].split("=", 1)[0]
        git(repo, "rm", "-q", "--ignore-unmatch", "--", path)
        return []
    p = git(repo, "cherry-pick", "--no-commit", src, check=False, env=bot_env())
    files = unmerged(repo) if p.returncode != 0 else []
    if p.returncode != 0 and not files and "could not apply" not in p.stderr:
        # a merge with conflicts says "could not apply" (rerere may have solved them all since);
        # anything else (untracked file in the way, dirty index) means nothing was merged
        raise StackError(f"cherry-pick {src[:12]} failed before merging anything:\n{p.stderr}")
    left = []
    for f in files:
        state = next(l[:2] for l in out(repo, "status", "--porcelain", "--", f).splitlines())
        if f in skip_paths:
            continue  # restored below
        if f == "Cargo.lock":
            git(repo, "checkout", "--ours", "--", f)
            git(repo, "add", f)
        elif state == "UD" and git(repo, "cat-file", "-e", f"{src}:{f}", check=False).returncode != 0:
            # The source deletes a file the new base changed: the deletion is the source's intent.
            git(repo, "rm", "-q", "--", f)
        else:
            left.append(f)
    for f in skip_paths:  # fork-only files the ci step writes itself: back to HEAD's state
        if git(repo, "cat-file", "-e", f"HEAD:{f}", check=False).returncode == 0:
            git(repo, "checkout", "HEAD", "--", f)
        else:
            git(repo, "rm", "-q", "--cached", "-f", "--ignore-unmatch", "--", f)
            (Path(repo) / f).unlink(missing_ok=True)
    if p.returncode != 0 and not left:
        git(repo, "cherry-pick", "--quit", check=False)
    return left


def step_message(repo, st, shas, extra_body=""):
    first = shas[0]
    subject = out(repo, "log", "-1", "--format=%s", first) if st["subject"] == "=" else st["subject"]
    body = out(repo, "log", "-1", "--format=%b", first)
    lines = [l for l in body.splitlines() if not l.startswith("Co-Authored-By:")]
    coauth = []
    for s in shas:
        for l in out(repo, "log", "-1", "--format=%b", s).splitlines():
            if l.startswith("Co-Authored-By:") and l not in coauth:
                coauth.append(l)
    text = subject + "\n\n" + "\n".join(lines).strip()
    if len(shas) > 1:
        text += "\n\nFolded in from the fork's earlier history:\n" + "".join(
            f"- {out(repo, 'log', '-1', '--format=%h %s', s)}\n" for s in shas)
    if extra_body:
        text += "\n\n" + extra_body.strip()
    if coauth:
        text += "\n\n" + "\n".join(coauth)
    return text.strip() + "\n"


def run_steps(repo, steps, gitconfig, args, report, key, on_special=None):
    """Replay `steps` (fix / ci / drop / regenerated kinds) on the checked-out base, one commit each.

    A conflict that rerere cannot solve stops the run with the tree left conflicted (resolve it,
    `git add`, run `replay.py --record`, run again), or with --skip-conflicts is listed and skipped."""
    for st in steps:
        kind = st["kind"].removeprefix("krun-")
        label = st["subject"] if st["subject"] != "=" and kind != "drop" else \
            out(repo, "log", "-1", "--format=%s", covered(st["sources"][0]))
        if kind == "drop":
            report["dropped"].append({"leg": key, "commit": label, "sources": st["sources"], "why": st["subject"],
                                      "folder": st["folder"]})
            continue
        if st["upstream"] != "-" and upstream_merged(repo, st["upstream"], "HEAD"):
            report["dropped"].append({"leg": key, "commit": label, "why": f"{st['upstream']} merged upstream"})
            continue
        if kind in ("deps", "version"):
            on_special(st)
            continue
        shas = []
        conflict = None
        for s in st["sources"]:
            if applied(s) == "-":
                continue
            left = apply_source(repo, applied(s), gitconfig)
            shas.append(full_sha(repo, covered(s) if s.startswith("rm:") else applied(s)))
            if left:
                conflict = (s, left)
                break
        if conflict:
            s, left = conflict
            entry = {"leg": key, "fix": label, "line": st["line"], "source": s, "files": left}
            if args.skip_conflicts:
                git(repo, "cherry-pick", "--quit", check=False)
                git(repo, "reset", "-q", "--hard", "HEAD")
                git(repo, "clean", "-qfd", "-e", ".scratch")
                report["conflicts"].append(entry)
                continue
            report["conflicts"].append(entry)
            raise StackError(f"{key}: conflict in `{label}` (manifest line {st['line']}) applying {s[:12]} "
                             f"in: {', '.join(left)}. The tree in {repo} is left as it is: resolve, `git add`, "
                             f"run `replay.py --record --repo {repo}`, then run the replay again.")
        if kind == "ci" and on_special:
            on_special(st)
        if git(repo, "diff", "--cached", "--quiet", check=False).returncode == 0:
            report["dropped"].append({"leg": key, "commit": label, "why": "empty on the new base (already upstream)"})
            continue
        if any(f == "Cargo.lock" for f in out(repo, "diff", "--cached", "--name-only").splitlines()) \
                and gitconfig is not None and key == "msb":
            cargo_refresh(repo, gitconfig)
            git(repo, "add", "Cargo.lock")
        a = out(repo, "log", "-1", "--format=%an%x00%ae%x00%aI", shas[0]).split("\x00")
        env = bot_env({"GIT_AUTHOR_NAME": a[0], "GIT_AUTHOR_EMAIL": a[1], "GIT_AUTHOR_DATE": a[2]})
        subprocess.run(["git", "commit", "-q", "--no-verify", "-F", "-"], cwd=repo,
                       input=step_message(repo, st, shas), text=True, check=True, env=env)
        report["picked"].append({"leg": key, "commit": label, "folder": st["folder"], "sources": len(shas),
                                 "sha": out(repo, "rev-parse", "HEAD")})


def stack_txt(steps):
    head = """# puddle fork patch stack: how .github/puddle/replay.py rebuilds the `puddle` branch on a new
# upstream release (fork-only file, generated from the restack manifest). One commit per fix: every
# commit on `puddle` since its upstream base matches one rule; an unmatched commit stops the replay,
# so a new fix gets a line here when it lands.
#
# Columns, separated by " | ":
#   action    pick     cherry-pick the commit; dropped when it comes out empty (upstream has it)
#             deps     regenerate: [patch.crates-io] for the libkrun, russh and imago forks
#             version  regenerate as the last commit: workspace version and `=` pins become
#                      <release>-puddle.N; the commit's other files (not Cargo.*) are kept
#   match     the commit subject; a trailing * matches a prefix. First matching line wins.
#   folder    puddle's upstream-issues/ folder (the filing list), or -
#   upstream  owner/repo#N of the upstream PR once filed, or -. A merged PR whose merge commit is
#             in the new release drops the commit.
#
# action  | match | folder | upstream
"""
    rows = []
    for st in steps:
        if st["kind"] == "fix":
            rows.append(("pick", st["subject"], st["folder"], st["upstream"]))
        elif st["kind"] == "deps":
            rows.append(("deps", "build: use the puddle forks*", "-", "-"))
        elif st["kind"] == "ci":
            rows.append(("pick", "ci(puddle):*", "-", "-"))
        elif st["kind"] == "version":
            rows.append(("version", "build: version the puddle fork as*", "-", "-"))
    return head + "".join(" | ".join(r) + "\n" for r in rows)


def restack(args, repo, work, gitconfig, report):
    steps, sources, krun_sources = load_restack(args.restack)
    msb_steps = [s for s in steps if not s["kind"].startswith("krun-")]
    krun_steps = [s for s in steps if s["kind"].startswith("krun-")]
    for s in msb_steps:  # a "=" subject is resolved once, from the msb clone
        if s["subject"] == "=" and s["kind"] == "fix":
            s["subject"] = out(repo, "log", "-1", "--format=%s", applied(s["sources"][0]))

    prev_tag = out(repo, "describe", "--tags", "--first-parent", "--abbrev=0", "--match", "v*-puddle.*", args.stack_ref)
    prev_base = out(repo, "rev-parse", f"{prev_tag.split('-puddle.')[0]}^{{commit}}")
    old = out(repo, "rev-parse", args.stack_ref)
    expected = out(repo, "rev-list", "--reverse", "--first-parent", "--no-merges", f"{prev_base}..{old}").split()
    for ref in sources:
        expected += [c for c in out(repo, "rev-list", "--reverse", "--no-merges", f"{old}..{ref}").split()
                     if c not in expected]
    check_coverage(repo, msb_steps, expected, "msb")
    report.update({"previous_tag": prev_tag, "previous_base": prev_tag.split("-puddle.")[0], "stack_ref": old,
                   "stack_size": len(expected), "conflicts": [], "mode": "restack"})

    up = args.upstream_sha
    up_toml = out(repo, "show", f"{up}:Cargo.toml")
    up_lock = out(repo, "show", f"{up}:Cargo.lock") + "\n"
    up_version = re.search(r'^\[workspace\.package\]\n(?:(?!\[)[^\n]*\n)*?version = "([^"]+)"', up_toml, re.M).group(1)
    up_pin = cargo_toml_pin(up_toml, "msb_krun")
    cur_toml = out(repo, "show", f"{old}:Cargo.toml")
    report["release"] = {"workspace_version": up_version, "msb_krun_pin": up_pin,
                         "russh_lock": lock_versions(up_lock, "russh")}

    # libkrun leg: the manifest's krun lines, squashed one commit per fix on the release's msb_krun commit.
    path = Path(args.work) / "libkrun"
    ensure_clone(path, LIBKRUN_URL, LIBKRUN_UPSTREAM)
    enable_rerere(path, args.rr_cache and Path(args.rr_cache) / "libkrun")
    cur_pin = re.search(rf'git = "https://github.com/{OLD_OWNERS}/libkrun", (branch|tag) = "([^"]+)"', cur_toml)
    cur_tip = out(path, "rev-parse", f"refs/tags/{cur_pin.group(2)}^{{commit}}")
    git(path, "fetch", "-q", "upstream", LIBKRUN_UPSTREAM_BRANCH)
    cur_base = out(path, "merge-base", cur_tip, f"upstream/{LIBKRUN_UPSTREAM_BRANCH}")
    k_expected = out(path, "rev-list", "--reverse", "--no-merges", f"{cur_base}..{cur_tip}").split()
    for ref in krun_sources:
        k_expected += [c for c in out(path, "rev-list", "--reverse", "--no-merges", f"{cur_tip}..origin/{ref}").split()
                       if c not in k_expected]
    check_coverage(path, krun_steps, k_expected, "libkrun")
    base, how = krun_base_for(path, up_pin)
    branch, tag = f"puddle-{up_pin}", f"msb_krun-v{up_pin}-puddle.1"
    git(path, "checkout", "-q", "-f", "-B", branch, base)
    run_steps(path, krun_steps, None, args, report, "libkrun")
    git(path, "tag", "-f", tag, "HEAD")
    sync_rerere(path, args.rr_cache and Path(args.rr_cache) / "libkrun")
    rebuilt = out(path, "rev-parse", "HEAD")
    pub = published_leg(path, tag, rebuilt)
    krun = {"branch": branch, "tag": tag, "sha": pub or rebuilt, "base": base, "base_version": up_pin,
            "pin": up_pin, "crates": lock_registry_packages(up_lock, "msb_krun"), "local": pub is None, "path": str(path)}
    report["legs"].append({"leg": "libkrun", "state": "restacked", "branch": branch, "tag": tag, "base": base,
                           "base_found_by": how, "sha": krun["sha"],
                           "kept": [p["commit"] for p in report["picked"] if p["leg"] == "libkrun"]})
    russh, info = russh_leg(args, cur_toml, up_lock)
    report["legs"].append(info)
    imago, info = imago_leg(cur_toml, up_lock)
    report["legs"].append(info)
    gitconfig.write_text("".join(f'[url "file://{leg["path"]}"]\n\tinsteadOf = {url}\n'
                                 for leg, url in ((krun, LIBKRUN_URL), (russh, RUSSH_URL)) if leg and leg["local"]))

    git(repo, "checkout", "-q", "-f", "--detach", up)
    git(repo, "clean", "-qfdx", "-e", ".scratch")
    enable_rerere(repo, args.rr_cache and Path(args.rr_cache) / "msb")
    date = datetime.date.today().isoformat()
    version_srcs = []

    def special(st):
        if st["kind"] == "deps":
            write_cargo_toml(repo, krun, russh, krun["pin"], imago)
            cargo_refresh(repo, gitconfig)
            git(repo, "add", "Cargo.toml", "Cargo.lock")
            msg = deps_message(krun, russh, imago, args.upstream_tag, date, report)
            commit_msg(repo, msg)
            report["regenerated"].append(msg.splitlines()[0])
        elif st["kind"] == "ci":
            (Path(repo) / ".github/puddle").mkdir(parents=True, exist_ok=True)
            (Path(repo) / OWN_PATHS[0]).write_text(stack_txt(msb_steps))
            shutil.copyfile(Path(__file__).resolve(), Path(repo) / OWN_PATHS[1])
            git(repo, "add", "--", *OWN_PATHS)
        elif st["kind"] == "version":
            version_srcs.extend(st["sources"])

    run_steps(repo, msb_steps, gitconfig, args, report, "msb", on_special=special)
    sync_rerere(repo, args.rr_cache and Path(args.rr_cache) / "msb")
    finish(args, repo, work, gitconfig, report, up, up_version, version_srcs, date, krun, russh)


def deps_message(krun, russh, imago, upstream_tag, date, report):
    lines = [f"- libkrun: msb_krun and msb_krun_utils pinned to ={krun['pin']}; every msb_krun_* crate from "
             f"{FORK_OWNER}/libkrun tag `{krun['tag']}` ({krun['sha'][:12]}), msb_krun {krun['base_version']} plus "
             f"the puddle libkrun fixes."]
    if russh:
        lines.append(f"- russh: {', '.join(russh['crates'])} from {FORK_OWNER}/russh tag `{russh['tag']}`, russh "
                     f"{russh['base_version']} plus the fix for the session wedge when the peer closes a channel with "
                     f"queued data (puddle upstream-issues/russh-peer-close-pending-data-wedge/).")
    if imago:
        lines.append(f"- imago: msb-imago from {FORK_OWNER}/imago tag `{imago['tag']}`, msb-imago {imago['base_version']} "
                     f"plus `File::sync()` using fdatasync instead of fsync (puddle upstream-issues/msb-guest-fsync-latency/).")
    body = "[patch.crates-io] takes the fork dependencies:\n\n" + "\n".join(lines) + f"""

Regenerated by .github/puddle/replay.py for {upstream_tag}.

Change note (Apache-2.0 section 4(b)): this commit modifies Cargo.toml and Cargo.lock. Changed for
the puddle fork by its replay job, {date}."""
    return message("build: use the puddle forks of libkrun, russh and imago", body)


# ------------------------------------------------------------------------------------------ main
def message(subject, body):
    return subject + "\n\n" + body.strip() + "\n"


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--repo", default=".")
    ap.add_argument("--stack-ref", default="origin/puddle")
    ap.add_argument("--merge-onto", help="branch tip the merge commit moves forward from (default: --stack-ref); "
                    "for a restack from an older stack while `puddle` already holds a newer one")
    ap.add_argument("--upstream-tag", required=True, help="release tag name, e.g. v0.7.8")
    ap.add_argument("--upstream-sha", required=True)
    ap.add_argument("--version", required=True, help="fork version, e.g. 0.7.8-puddle.1")
    ap.add_argument("--manifest", required=True)
    ap.add_argument("--work", required=True)
    ap.add_argument("--force-legs", action="store_true", help="replay libkrun/russh even if their base did not move")
    ap.add_argument("--inject-conflict", action="store_true", help="dry-run test: make the first fix conflict")
    ap.add_argument("--restack", help="restack manifest: rebuild the stack as one commit per fix (see load_restack)")
    ap.add_argument("--rr-cache", help="directory holding recorded conflict resolutions (rerere), synced both ways")
    ap.add_argument("--skip-conflicts", action="store_true",
                    help="restack: list a fix rerere cannot solve and go on without it (triage; never published)")
    ap.add_argument("--record", action="store_true",
                    help="record the resolution made by hand in --repo's conflicted tree (git rerere) and exit")
    if "--record" in sys.argv:
        rp = argparse.ArgumentParser()
        rp.add_argument("--record", action="store_true")
        rp.add_argument("--repo", default=".")
        rp.add_argument("--rr-cache")
        args = rp.parse_args()
        return record(Path(args.repo).resolve(), args.rr_cache)
    args = ap.parse_args()

    repo = Path(args.repo).resolve()
    work = Path(args.work).resolve()
    work.mkdir(parents=True, exist_ok=True)
    args.work = str(work)
    gitconfig = work / "gitconfig"
    gitconfig.write_text("")
    report = {"upstream_tag": args.upstream_tag, "upstream_sha": args.upstream_sha, "version": args.version,
              "picked": [], "dropped": [], "regenerated": [], "legs": [], "status": "error"}
    try:
        enable_rerere(repo)
        (restack if args.restack else replay)(args, repo, work, gitconfig, report)
        report["status"] = "ok" if not report.get("conflicts") else "conflicts skipped"
        code = 0
    except StackError as e:
        report["status"] = "conflict"
        report["error"] = str(e)
        code = 3
    (work / "report.json").write_text(json.dumps(report, indent=2))
    (work / "summary.md").write_text(summary(report))
    print(summary(report))
    return code


def replay(args, repo, work, gitconfig, report):
    rules = load_manifest(args.manifest)
    prev_tag = out(repo, "describe", "--tags", "--first-parent", "--abbrev=0", "--match", "v*-puddle.*", args.stack_ref)
    prev_base_tag = prev_tag.split("-puddle.")[0]
    prev_base = out(repo, "rev-parse", f"{prev_base_tag}^{{commit}}")
    if git(repo, "merge-base", "--is-ancestor", prev_base, args.stack_ref, check=False).returncode != 0:
        raise StackError(f"{prev_base_tag} is not an ancestor of {args.stack_ref}")
    stack = out(repo, "rev-list", "--reverse", "--first-parent", "--no-merges", f"{prev_base}..{args.stack_ref}").splitlines()
    report.update({"previous_tag": prev_tag, "previous_base": prev_base_tag, "stack_ref": out(repo, "rev-parse", args.stack_ref),
                   "stack_size": len(stack)})

    plan, unknown = [], []
    for c in stack:
        subj = out(repo, "log", "-1", "--format=%s", c)
        r = rule_for(rules, subj)
        if r is None:
            unknown.append(f"{c[:12]} {subj}")
        plan.append((c, subj, r))
    if unknown:
        raise StackError("commits on the fork branch that no line in .github/puddle/stack.txt matches "
                         "(add them, then rerun):\n" + "\n".join(f"- {u}" for u in unknown))
    exact = [r for r in rules if not r["match"].endswith("*")]
    seen = {id(r) for _, _, r in plan}
    report["manifest_not_on_branch"] = [r["match"] for r in exact if id(r) not in seen]

    up = args.upstream_sha
    up_toml = out(repo, "show", f"{up}:Cargo.toml")
    up_lock = out(repo, "show", f"{up}:Cargo.lock") + "\n"
    up_version = re.search(r'^\[workspace\.package\]\n(?:(?!\[)[^\n]*\n)*?version = "([^"]+)"', up_toml, re.M).group(1)
    want_release = re.sub(r"^.*?v(\d+\.\d+\.\d+)$", r"\1", args.upstream_tag)
    if up_version != want_release:
        report["warning"] = f"workspace version at {args.upstream_tag} is {up_version}, not {want_release}"
    up_pin = cargo_toml_pin(up_toml, "msb_krun")
    cur_toml = out(repo, "show", f"{args.stack_ref}:Cargo.toml")
    report["release"] = {"workspace_version": up_version, "msb_krun_pin": up_pin,
                         "russh_lock": lock_versions(up_lock, "russh")}

    krun = russh = None
    if any(r and r["action"] in ("krun", "deps") for _, _, r in plan):
        krun, info = libkrun_leg(args, cur_toml, up_lock, up_pin)
        report["legs"].append(info)
    if any(r and r["action"] in ("russh", "deps") for _, _, r in plan):
        russh, info = russh_leg(args, cur_toml, up_lock)
        report["legs"].append(info)
    imago = None
    if any(r and r["action"] in ("imago", "deps") for _, _, r in plan):
        imago, info = imago_leg(cur_toml, up_lock)
        report["legs"].append(info)
    cfg = []
    for leg, url in ((krun, LIBKRUN_URL), (russh, RUSSH_URL)):
        if leg and leg["local"]:
            cfg.append(f'[url "file://{leg["path"]}"]\n\tinsteadOf = {url}\n')
    gitconfig.write_text("".join(cfg))

    git(repo, "checkout", "-q", "-f", "--detach", up)
    git(repo, "clean", "-qfdx", "-e", ".scratch")
    if args.inject_conflict:
        inject_conflict(repo, plan)

    applied_krun = applied_russh = applied_imago = None
    version_extra = []
    date = datetime.date.today().isoformat()
    for c, subj, r in plan:
        action = r["action"]
        if r["upstream"] != "-" and upstream_merged(repo, r["upstream"], up):
            report["dropped"].append({"commit": subj, "why": f"{r['upstream']} merged into {args.upstream_tag}"})
            continue
        if action == "pick":
            touches_lock = "Cargo.lock" in out(repo, "show", "--name-only", "--format=", c).splitlines()
            res = pick(repo, c, lock_ok=True, gitconfig=gitconfig)
            entry = {"commit": subj, "folder": r["folder"]}
            if res == "empty":
                report["dropped"].append({**entry, "why": "empty on the new base (already upstream)"})
            else:
                if touches_lock:
                    cargo_refresh(repo, gitconfig)
                    if git(repo, "diff", "--quiet", check=False).returncode != 0:
                        git(repo, "commit", "-q", "-a", "--amend", "--no-edit", env=bot_env())
                report["picked"].append(entry)
        elif action.startswith("rm:"):
            path = action[3:]
            if (repo / path).exists():
                git(repo, "rm", "-q", "--", path)
                git(repo, "commit", "-q", "-C", c, env=bot_env())
                report["picked"].append({"commit": subj, "folder": "-"})
            else:
                report["dropped"].append({"commit": subj, "why": f"{path} not in {args.upstream_tag}"})
        elif action == "version":
            version_extra.append(c)
        elif action == "deps":
            applied_krun, applied_russh, applied_imago = krun, russh, imago
            write_cargo_toml(repo, krun, russh, (krun or {}).get("pin") or up_pin, imago)
            cargo_refresh(repo, gitconfig)
            git(repo, "add", "Cargo.toml", "Cargo.lock")
            msg = deps_message(krun, russh, imago, args.upstream_tag, date, report)
            commit_msg(repo, msg)
            report["regenerated"].append(msg.splitlines()[0])
        elif action in ("krun", "russh", "imago"):
            if (action == "krun" and applied_krun) or (action == "russh" and applied_russh) \
                    or (action == "imago" and applied_imago):
                # A later commit that moved the same leg (e.g. a new fork commit in Cargo.lock):
                # the leg's single regenerated commit already pins the branch's current tip.
                report["dropped"].append({"commit": subj, "why": f"folded into the regenerated {action} commit"})
                continue
            if action == "krun":
                applied_krun = krun
            elif action == "russh":
                applied_russh = russh
            else:
                applied_imago = imago
            pin = (applied_krun or {}).get("pin") or up_pin
            write_cargo_toml(repo, applied_krun, applied_russh, pin, applied_imago)
            cargo_refresh(repo, gitconfig)
            if git(repo, "status", "--porcelain", check=False).stdout.strip() == "":
                report["dropped"].append({"commit": subj, "why": "no patch needed any more"})
                continue
            git(repo, "add", "Cargo.toml", "Cargo.lock")
            leg = {"krun": applied_krun, "russh": applied_russh, "imago": applied_imago}[action]
            msg = leg_message(action, leg, krun, russh, args.upstream_tag, date, report)
            commit_msg(repo, msg)
            report["regenerated"].append(msg.splitlines()[0])

    finish(args, repo, work, gitconfig, report, up, up_version, version_extra, date, applied_krun, applied_russh)


def finish(args, repo, work, gitconfig, report, up, up_version, version_extra, date, applied_krun, applied_russh):
    # Version commit: other files of the version commits (e.g. the PREBUILT_VERSION suffix strip),
    # then the workspace version and the internal `=` pins.
    for c in version_extra:
        files = [f for f in out(repo, "show", "--name-only", "--format=", c).splitlines()
                 if f not in ("Cargo.toml", "Cargo.lock")]
        if files:
            p = run(["git", "format-patch", "-1", "--stdout", c, "--", *files], cwd=repo)
            a = subprocess.run(["git", "apply", "--3way", "--index"], cwd=repo, input=p.stdout, text=True,
                               capture_output=True)
            if a.returncode != 0:
                raise StackError(f"version commit {c[:12]}: its {', '.join(files)} change does not apply:\n{a.stderr}")
    n = write_version(repo, up_version, args.version)
    cargo_refresh(repo, gitconfig)
    git(repo, "add", "-A", "--", ".", ":!.scratch")
    msg = message(f"build: version the puddle fork as {args.version}", f"""
puddle's bundled-runtime check reads the version embedded in msb.exe and accepts exactly
<release>-puddle.N, and the SDK only takes the modern launch contract when msb's version equals its
own. So the workspace version and the internal crates' exact pins ({n}) carry the fork tag's
version: {args.version} for tag v{args.version}.

PREBUILT_VERSION drops the pre-release suffix, so the build scripts and setup still fetch agentd and
the runtime bundle from the upstream {args.upstream_tag} release.

Regenerated by .github/puddle/replay.py for {args.upstream_tag}.

Change note (Apache-2.0 section 4(b)): this commit modifies Cargo.toml, Cargo.lock and
crates/utils/lib/lib.rs. Changed for the puddle fork by its auto-bump job, {date}.""")
    commit_msg(repo, msg)
    report["regenerated"].append(msg.splitlines()[0])

    tip = out(repo, "rev-parse", "HEAD")
    git(repo, "branch", "-f", "puddle-candidate", tip)
    report["tip"] = tip
    onto = out(repo, "rev-parse", args.merge_onto or args.stack_ref)
    report["diff_vs_stack_ref"] = out(repo, "diff", "--stat", onto, tip)
    # Merge commit for the `puddle` branch: the new stack as first parent (so the next replay
    # walks it with --first-parent) and the old branch as second, tree = new stack.
    merge = out(repo, "commit-tree", f"{tip}^{{tree}}", "-p", tip, "-p", onto,
                "-m", f"Merge the puddle stack on {args.upstream_tag} ({args.version})\n\n"
                      f"Tree = v{args.version}. The old branch is the second parent, so `puddle` moves\n"
                      f"forward without a force push.")
    git(repo, "branch", "-f", "puddle-candidate-merge", merge)
    report["merge"] = merge

    # msb.bundle needs only the release commit (gate jobs); msb-merge.bundle also the old branch.
    bundles = {"msb": {"bundle": "msb.bundle", "merge_bundle": "msb-merge.bundle", "sha": tip, "merge": merge,
                       "base": up, "old": onto}}
    git(repo, "bundle", "create", str(work / "msb.bundle"), "puddle-candidate", f"^{up}")
    git(repo, "bundle", "create", str(work / "msb-merge.bundle"), "puddle-candidate-merge", "^puddle-candidate",
        f"^{bundles['msb']['old']}")
    for name, leg, url in (("libkrun", applied_krun, LIBKRUN_URL), ("russh", applied_russh, RUSSH_URL)):
        if leg and leg["local"]:
            git(leg["path"], "bundle", "create", str(work / f"{name}.bundle"), f"refs/heads/{leg['branch']}", f"refs/tags/{leg['tag']}", f"^{leg['base']}")
            bundles[name] = {"bundle": f"{name}.bundle", "url": url, "branch": leg["branch"], "tag": leg["tag"], "sha": leg["sha"],
                             "base": leg["base"], "base_url": LIBKRUN_UPSTREAM if name == "libkrun" else RUSSH_UPSTREAM,
                             "base_version": leg["base_version"]}
    (work / "candidate.json").write_text(json.dumps(bundles, indent=2))
    report["candidate"] = bundles


def record(repo, rr_cache):
    """After a hand resolution: every conflicted file must be resolved and staged; rerere keeps it."""
    left = unmerged(repo)
    if left:
        print(f"still unmerged (resolve and `git add` them first): {', '.join(left)}")
        return 2
    markers = git(repo, "diff", "--cached", "--check", check=False).stdout
    if "conflict marker" in markers:
        print(markers)
        return 2
    git(repo, "rerere")
    print(out(repo, "rerere", "status") or "(nothing pending)")
    git(repo, "cherry-pick", "--quit", check=False)
    sync_rerere(repo, rr_cache)
    print("recorded; run the replay again")
    return 0


def commit_msg(repo, msg):
    subprocess.run(["git", "commit", "-q", "-F", "-"], cwd=repo, input=msg, text=True, check=True, env=author_env())


def leg_message(action, leg, krun, russh, upstream_tag, date, report):
    if action == "krun":
        info = next(i for i in report["legs"] if i["leg"] == "libkrun")
        fixes = info.get("kept") or []
        body = f"""
Pin msb_krun and msb_krun_utils to ={leg['pin']} and take every msb_krun_* crate from
{FORK_OWNER}/libkrun tag `{leg['tag']}` ({leg['sha'][:12]}) through [patch.crates-io]. That tag is
msb_krun {leg['base_version']} plus the puddle libkrun fixes{':' if fixes else '.'}
""" + "".join(f"- {f}\n" for f in fixes) + f"""
Regenerated by .github/puddle/replay.py for {upstream_tag} (libkrun leg: {info['state']}).

Change note (Apache-2.0 section 4(b)): this commit modifies Cargo.toml and Cargo.lock. Changed for
the puddle fork by its auto-bump job, {date}."""
        return message(f"build: use the puddle libkrun fork (msb_krun {leg['pin']})", body)
    if action == "imago":
        info = next(i for i in report["legs"] if i["leg"] == "imago")
        body = f"""
[patch.crates-io] takes msb-imago from {FORK_OWNER}/imago tag `{leg['tag']}`: msb-imago {leg['base_version']}
plus `File::sync()` using fdatasync instead of fsync (puddle upstream-issues/msb-guest-fsync-latency/).
The tag is based on the exact crates.io release, so the guest's flush path changes in nothing else.

Regenerated by .github/puddle/replay.py for {upstream_tag} (imago leg: {info['state']}).

Change note (Apache-2.0 section 4(b)): this commit modifies Cargo.toml and Cargo.lock. Changed for
the puddle fork by its auto-bump job, {date}."""
        return message(f"build: use the puddle imago fork (msb-imago {leg['base_version']} with fdatasync)", body)
    info = next(i for i in report["legs"] if i["leg"] == "russh")
    body = f"""
[patch.crates-io] takes {', '.join(leg['crates'])} from {FORK_OWNER}/russh tag `{leg['tag']}`
({leg['sha'][:12]}): russh {leg['base_version']} plus the fix for the session wedge when the peer
closes a channel with queued data (puddle upstream-issues/russh-peer-close-pending-data-wedge/).

Regenerated by .github/puddle/replay.py for {upstream_tag} (russh leg: {info['state']}).

Change note (Apache-2.0 section 4(b)): this commit modifies Cargo.toml and Cargo.lock. Changed for
the puddle fork by its auto-bump job, {date}."""
    return message(f"build: use the puddle russh fork ({leg['base_version']} with the peer-close fix)", body)


def upstream_merged(repo, ref, up):
    m = re.fullmatch(r"([\w.-]+/[\w.-]+)#(\d+)", ref)
    if not m:
        raise StackError(f"stack.txt upstream column: want owner/repo#N, got {ref}")
    p = run(["gh", "api", f"repos/{m.group(1)}/pulls/{m.group(2)}", "--jq", ".merge_commit_sha + \" \" + (.merged|tostring)"],
            check=False)
    if p.returncode != 0:
        return False
    sha, merged = (p.stdout.strip().split() + ["", ""])[:2]
    if merged != "true":
        return False
    git(repo, "fetch", "-q", f"https://github.com/{m.group(1)}", sha, check=False)
    return git(repo, "merge-base", "--is-ancestor", sha, up, check=False).returncode == 0


def inject_conflict(repo, plan):
    """Dry-run test only: change, on the new base, a line that the first fix also changes."""
    for c, subj, r in plan:
        if r["action"] != "pick":
            continue
        diff = out(repo, "show", "--format=", "-U0", c)
        f = re.search(r"^\+\+\+ b/(.+)$", diff, re.M)
        h = re.search(r"^@@ -(\d+)", diff, re.M)
        if not f or not h:
            continue
        path, line = Path(repo) / f.group(1), max(int(h.group(1)), 1)
        lines = path.read_text().splitlines(keepends=True)
        lines[line - 1] = "// puddle auto-bump dry run: forced conflict\n" + lines[line - 1]
        path.write_text("".join(lines))
        git(repo, "commit", "-q", "-am", "test: forced conflict (auto-bump dry run only)", env=author_env())
        return
    raise StackError("inject-conflict: no pick commit to conflict with")


def summary(rep):
    s = [f"### Replay of the puddle stack on `{rep['upstream_tag']}` as `{rep['version']}`: **{rep['status']}**", ""]
    if rep.get("previous_tag"):
        s.append(f"Previous fork tag `{rep['previous_tag']}` (base `{rep['previous_base']}`), "
                 f"{rep.get('stack_size', '?')} commits on the branch since that base.")
    if rep.get("release"):
        r = rep["release"]
        s.append(f"Release: workspace version {r['workspace_version']}, msb_krun pin ={r['msb_krun_pin']}, "
                 f"russh in Cargo.lock {', '.join(r['russh_lock'])}.")
    if rep.get("warning"):
        s.append(f"\n**Warning:** {rep['warning']}")
    if rep.get("error"):
        s += ["", "**Stopped:**", "", rep["error"]]
    if rep.get("conflicts"):
        s += ["", f"**Conflicts ({len(rep['conflicts'])}):**"] + [
            f"- {c['leg']}: `{c['fix']}` (manifest line {c['line']}), source {c['source'][:12]}: {', '.join(c['files'])}"
            for c in rep["conflicts"]]
    if rep["picked"]:
        s += ["", "Picked:"] + [f"- {p['commit']}" + (f" ({p['folder']})" if p.get("folder", "-") != "-" else "") for p in rep["picked"]]
    if rep["dropped"]:
        s += ["", "Dropped:"] + [f"- {d['commit']}: {d['why']}" for d in rep["dropped"]]
    if rep["regenerated"]:
        s += ["", "Regenerated:"] + [f"- {r}" for r in rep["regenerated"]]
    for leg in rep["legs"]:
        s += ["", f"{leg['leg']} leg: **{leg['state']}**" + "".join(
            f"; {k} `{v}`" for k, v in leg.items() if k in ("current_branch", "current_version", "release_pin",
                                                          "release_lock", "branch", "tag", "base", "sha", "base_found_by",
                                                          "tree_equal_to_current"))]
        if leg.get("kept") is not None:
            s += [f"  - kept: {k}" for k in leg["kept"]] + [f"  - dropped (empty): {d}" for d in leg.get("dropped", [])]
    if rep.get("manifest_not_on_branch"):
        s += ["", "stack.txt lines with no commit on the branch: " + "; ".join(rep["manifest_not_on_branch"])]
    if rep.get("tip"):
        s += ["", f"New stack tip `{rep['tip']}`, merge commit for `puddle` `{rep['merge']}`.", "",
              "Tree difference against the current fork branch:", "", "```", rep["diff_vs_stack_ref"] or "(none)", "```"]
    return "\n".join(s) + "\n"


if __name__ == "__main__":
    sys.exit(main())
